package com.example.textapi.service;

import org.junit.jupiter.api.BeforeAll;
import static org.junit.jupiter.api.Assertions.assertThrows;
import org.junit.jupiter.api.extension.ExtendWith;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.AfterEach;

import org.mockito.Mockito;
import org.mockito.Mock;
import static org.mockito.Mockito.mock;
import org.mockito.junit.jupiter.MockitoExtension;
import com.example.textapi.utils.TextConversionUtil;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

public class TextServiceGeneratedAiTests {

    private TextService textService;

    @BeforeEach
    void setUp() {
        // Reset state before each test
        textService = new TextService();
    }

    @Test
    void testReverse_regularString() {
        // GIVEN
        String input = "abc123";
        // WHEN
        String result = textService.reverse(input);
        // THEN
        assertEquals("321cba", result);
    }

    @Test
    void testReverse_nullInput_throwsNullPointerException() {
        // GIVEN
        String input = null;
        // WHEN / THEN
        assertThrows(NullPointerException.class, () -> textService.reverse(input));
    }

    @Test
    void testUppercase_convertsToUppercase() {
        // GIVEN
        String input = "Hello, TeSt";
        // WHEN
        String result = textService.uppercase(input);
        // THEN
        assertEquals("HELLO, TEST", result);
    }

    @Test
    void testReplace_replacesAllOccurrences() {
        // GIVEN
        String input = "aba";
        String target = "a";
        String replacement = "x";
        // WHEN
        String result = textService.replace(input, target, replacement);
        // THEN
        assertEquals("xbx", result);
    }

    @Test
    void testRemoveVowels_removesAllVowelsCaseInsensitive() {
        // GIVEN
        String input = "Hello World AEIOU aeiou";
        // WHEN
        String result = textService.removeVowels(input);
        // THEN
        // Expect vowels removed, preserving spaces and other characters
        assertEquals("Hll Wrld  ", result);
    }

    @Test
    void testRemoveConsonants_removesAllConsonantsCaseInsensitive() {
        // GIVEN
        String input = "Hello123!";
        // WHEN
        String result = textService.removeConsonants(input);
        // THEN
        // Consonants removed, digits and punctuation remain
        assertEquals("eo123!", result);
    }

    @Test
    void testCountOccurrence_caseInsensitiveWholeWordMatching() {
        // GIVEN
        String input = "Java java JavaScript java.";
        String keyword = "java";
        // WHEN
        int count = textService.countOccurrence(input, keyword);
        // THEN
        // Should match only whole words "Java", "java", and "java." counts as whole word due to word boundary
        assertEquals(3, count);
    }

    @Test
    void testHelloworld_returnsHelloWorldConstant() {
        // GIVEN
        // WHEN
        String result = textService.helloworld();
        // THEN
        assertEquals("Hello, World!", result);
    }

    @Test
    void testConvertJsonToYaml_validJsonProducesYamlLikeOutput() {
        // GIVEN
        String json = "{\"a\":1,\"b\":\"text\"}";
        // WHEN
        String yaml = textService.convertJsonToYaml(json);
        // THEN
        // Basic checks: YAML output should contain key names and values
        assertNotNull(yaml);
        assertTrue(yaml.contains("a:") || yaml.contains("a: 1"));
        assertTrue(yaml.contains("b:") || yaml.contains("b: \"text\"") || yaml.contains("b: text"));
    }

    @Test
    void testConvertJsonToXml_validJsonProducesXmlLikeOutput() {
        // GIVEN
        String json = "{\"a\":1}";
        // WHEN
        String xml = textService.convertJsonToXml(json);
        // THEN
        assertNotNull(xml);
        // Basic check: XML output should contain an element for "a" and the value "1"
        assertTrue(xml.contains("<a>") || xml.contains("a>1"));
        assertTrue(xml.contains("1"));
    }

    @Test
    void testGetRepeatedWords_countsAndFormatsRepeatedWords() {
        // GIVEN
        String input = "test test TEST hello";
        // WHEN
        List<String> repeated = textService.getRepeatedWords(input);
        // THEN
        assertNotNull(repeated);
        assertTrue(repeated.contains("test : 3"));
        assertEquals(1, repeated.size());
    }

    @Test
    void testStats_computesAllExpectedMetrics() {
        // GIVEN
        String input = "Hello world\nHello";
        // WHEN
        Map<String, Object> stats = textService.stats(input);
        // THEN
        assertNotNull(stats);
        // length
        assertEquals(Integer.valueOf(17), stats.get("length"));
        // wordCount (Hello world Hello) -> 3
        assertEquals(Integer.valueOf(3), stats.get("wordCount"));
        // lineCount (split by \n) -> 2
        assertEquals(Integer.valueOf(2), stats.get("lineCount"));
        // VowelCount -> 5 (e,o,o,e,o)
        assertEquals(Integer.valueOf(5), stats.get("VowelCount"));
        // ConsonantCount -> 10
        assertEquals(Integer.valueOf(10), stats.get("ConsonantCount"));
        // RepeatedWords should contain "hello : 2"
        Object repeatedObj = stats.get("RepeatedWords");
        assertTrue(repeatedObj instanceof List);
        @SuppressWarnings("unchecked")
        List<String> repeated = (List<String>) repeatedObj;
        assertTrue(repeated.contains("hello : 2"));
    }

    @Test
    void testConvertJsonToYaml_invalidJsonReturnsErrorMessage() {
        // GIVEN
        String invalidJson = "{invalid:}";
        // WHEN
        String result = textService.convertJsonToYaml(invalidJson);
        // THEN
        assertNotNull(result);
        assertTrue(result.startsWith("Error converting JSON to YAML"));
    }

    @Test
    void testConvertJsonToXml_invalidJsonReturnsErrorMessage() {
        // GIVEN
        String invalidJson = "{invalid:}";
        // WHEN
        String result = textService.convertJsonToXml(invalidJson);
        // THEN
        assertNotNull(result);
        assertTrue(result.startsWith("Error converting JSON to XML"));
    }
}

