package com.example.textapi.service;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.extension.ExtendWith;
import static org.junit.jupiter.api.Assertions.assertThrows;
import org.junit.jupiter.api.BeforeAll;

import org.mockito.junit.jupiter.MockitoExtension;
import static org.mockito.Mockito.mock;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import java.util.List;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class TextServiceGeneratedAiTests {

    private TextService service;

    @BeforeEach
    void setUp() {
        // Reset state before each test
        service = new TextService();
    }

    @Test
    void testReverse_regularString() {
        // GIVEN
        String input = "abc123";
        // WHEN
        String result = service.reverse(input);
        // THEN
        assertEquals("321cba", result);
    }

    @Test
    void testUppercase_emptyString() {
        // GIVEN
        String input = "";
        // WHEN
        String result = service.uppercase(input);
        // THEN
        assertEquals("", result);
    }

    @Test
    void testReplace_substringOccurrencesReplaced() {
        // GIVEN
        String input = "foo bar foo";
        String target = "foo";
        String replacement = "baz";
        // WHEN
        String result = service.replace(input, target, replacement);
        // THEN
        assertEquals("baz bar baz", result);
    }

    @Test
    void testRemoveVowels_mixedCaseRemovesAllVowels() {
        // GIVEN
        String input = "AbcE IoU!";
        // WHEN
        String result = service.removeVowels(input);
        // THEN
        assertEquals("bc !", result);
        // Ensure no vowels remain (case-insensitive)
        assertFalse(result.toLowerCase().matches(".*[aeiou].*"));
    }

    @Test
    void testRemoveConsonants_mixedCaseRemovesAllConsonants() {
        // GIVEN
        String input = "AbcE IoU!";
        // WHEN
        String result = service.removeConsonants(input);
        // THEN
        assertEquals("AE IoU!", result);
        // Ensure no consonants remain (case-insensitive)
        assertFalse(result.toLowerCase().matches(".*[b-df-hj-np-tv-z].*"));
    }

    @Test
    void testCountOccurrence_caseInsensitiveWholeWordMatches() {
        // GIVEN
        String input = "Test test TEST testing";
        String keyword = "test";
        // WHEN
        int occurrences = service.countOccurrence(input, keyword);
        // THEN
        assertEquals(3, occurrences);
    }

    @Test
    void testHelloworld_constantValue() {
        // GIVEN
        // no special setup
        // WHEN
        String result = service.helloworld();
        // THEN
        assertEquals("Hello, World!", result);
    }

    @Test
    void testConvertJsonToYaml_containsExpectedFields() {
        // GIVEN
        String json = "{\"name\":\"John\",\"age\":30}";
        // WHEN
        String yaml = service.convertJsonToYaml(json);
        // THEN
        assertNotNull(yaml);
        assertTrue(yaml.contains("name"));
        assertTrue(yaml.contains("John"));
        assertTrue(yaml.contains("age"));
        assertTrue(yaml.contains("30"));
    }

    @Test
    void testConvertJsonToXml_containsExpectedElements() {
        // GIVEN
        String json = "{\"name\":\"John\",\"age\":30}";
        // WHEN
        String xml = service.convertJsonToXml(json);
        // THEN
        assertNotNull(xml);
        assertTrue(xml.contains("<name>John</name>"));
        assertTrue(xml.contains("<age>30</age>"));
    }

    @Test
    void testGetRepeatedWords_countsAndOrderPreserved() {
        // GIVEN
        String input = "This is is a test test Test";
        // WHEN
        List<String> repeated = service.getRepeatedWords(input);
        // THEN
        assertNotNull(repeated);
        assertEquals(2, repeated.size());
        assertEquals("is : 2", repeated.get(0));
        assertEquals("test : 3", repeated.get(1));
    }

    @Test
    void testStats_wordAndLineCountsAndRepeatedWords() {
        // GIVEN
        String input = "Hello hello\nWorld";
        // WHEN
        Map<String, Object> stats = service.stats(input);
        // THEN
        assertNotNull(stats);
        assertEquals(Integer.valueOf(3), stats.get("wordCount"));
        assertEquals(Integer.valueOf(2), stats.get("lineCount"));
        Object repeatedObj = stats.get("RepeatedWords");
        assertTrue(repeatedObj instanceof List);
        @SuppressWarnings("unchecked")
        List<String> repeated = (List<String>) repeatedObj;
        assertEquals(1, repeated.size());
        assertEquals("hello : 2", repeated.get(0));
    }
}

